  }

  if (selectsEnd && startDate) {
    return isMonthInRange(startDate, selectingDate, m, day);
  }

  if (selectsRange && startDate && !endDate) {
    return isMonthInRange(startDate, selectingDate, m, day);
  }

  return false;
